returns.expression:
{
        $schema: "http://json-schema.org/draft-07/schema#",
        title: "EUIX XML UI Specification Schema",
        description: "JSON Schema validator for EUIX Engine declarative XML components and applications",
        type: "object",
        properties: {
            uid_spec: {
                type: "object",
                properties: {
                    data_model: {
                        type: "object",
                        properties: {
                            state: {
                                type: "array",
                                items: {
                                    type: "object",
                                    required: ["id"],
                                    properties: {
                                        id: { type: "string" },
                                        type: { enum: ["string", "number", "boolean", "array", "object"] },
                                        scope: { enum: ["local", "global"] },
                                        persist: { type: "boolean" },
                                    },
                                },
                            },
                        },
                    },
                    api_config: {
                        type: "object",
                        properties: {
                            base_url: { type: "string" },
                            api_endpoint: {
                                type: "array",
                                items: {
                                    type: "object",
                                    required: ["url"],
                                    properties: {
                                        id: { type: "string" },
                                        url: { type: "string" },
                                        method: { enum: ["GET", "POST", "PUT", "DELETE", "PATCH"] },
                                        target: { type: "string" },
                                        auto_fetch: { type: "boolean" },
                                        persist: { enum: ["localStorage", "sessionStorage"] },
                                        queue_offline: { type: "boolean" },
                                    },
                                },
                            },
                        },
                    },
                },
            },
        },
    }
